<?php

declare(strict_types=1);
require_once __DIR__.'/../../includes/cors.php';require_once __DIR__.'/../../includes/response.php';require_once __DIR__.'/../../includes/helpers.php';require_once __DIR__.'/../../config/database.php';require_once __DIR__.'/../../includes/auth.php';require_once __DIR__.'/../../includes/admin-audit.php';
if($_SERVER['REQUEST_METHOD']!=='POST')json_response(['success'=>false,'message'=>'Method not allowed'],405);$user=require_auth($pdo);require_role($user,['super_admin']);$input=get_json_input();$noteId=filter_var($input['note_id']??0,FILTER_VALIDATE_INT,['options'=>['default'=>0,'min_range'=>1]]);if($noteId<=0)json_response(['success'=>false,'message'=>'note_id is required'],422);
try{$stmt=$pdo->prepare('SELECT n.id,n.tenant_id,n.body,t.name tenant_name FROM tenant_notes n INNER JOIN tenants t ON t.id=n.tenant_id WHERE n.id=:id LIMIT 1');$stmt->execute([':id'=>$noteId]);$note=$stmt->fetch();if(!$note)json_response(['success'=>false,'message'=>'یادداشت پیدا نشد.'],404);$pdo->prepare('DELETE FROM tenant_notes WHERE id=:id')->execute([':id'=>$noteId]);admin_audit_log($pdo,$user,'customer.note_deleted','tenant_note',$noteId,'یادداشت داخلی مشتری «'.$note['tenant_name'].'» حذف شد.',['body'=>$note['body']],null,['tenant_id'=>(int)$note['tenant_id']]);json_response(['success'=>true,'message'=>'یادداشت حذف شد.']);}catch(Throwable $e){error_log('[CUSTOMER_NOTE_DELETE] '.$e->getMessage());json_response(['success'=>false,'message'=>'حذف یادداشت ناموفق بود.'],500);}
